    // <auto-generated />
using System.Collections.Generic;
using System.Linq;
using Fanex.Excel.Enums;
using Fanex.Excel.Models;
using RiskControl.NonSportsGamesStatistics.Common;
using RiskControl.NonSportsGamesStatistics.Model;
using RiskControl.NonSportsGamesStatistics.UserNameView.Common;

    namespace RiskControl.NonSportsGamesStatistics.UserNameView.AssociatedAccount; 

    public class GridOptionBuilderServiceImp<TQuery>(GridOptionDataRowBuilderService gridDataRowBuilderService,
            GridOptionHeaderBuilderService headerBuilderService,
            GridOptionRemoveColumnService gridOptionRemoveColumnService)
        : GridOptionBuilderService<UserNameViewReportModel, TQuery>
        where TQuery: BaseStatisticQueryModel
    {
        private const int UserNameColumnIndex = 0;
        private const int CustIdColumnIndex = 1;
        private const int RoleColumnIndex = 2;

        public GridOptions BuildGridOptions(UserNameViewReportModel statistics, TQuery queryModel)
        {
            var gridOptions = new GridOptions
            {
                ShowTitle = true,
                TitleType = TitleType.TwoLineBlue,
                TitleInfoText = queryModel.Title,
                BodyRows = BuildBodyRows(statistics.Statistics, queryModel.IsNormalMode, queryModel.ViewByInteger),
                FooterRows = BuildFooter(statistics.GrandTotal, queryModel.IsNormalMode, queryModel.ViewByInteger),
                Columns = BuildColumns(queryModel),
                ShowFooter = true,
                ShowHighlightRow = false,
                ShowDistinctRow = false,
                ShowTree = true
            };

            gridOptions = gridOptionRemoveColumnService.RemoveColumn(gridOptions, queryModel.RemovalColumns);

            return gridOptions;
        }

        private List<HeaderColumns> BuildColumns(BaseStatisticQueryModel queryModel)
        {
            var headerColumns = headerBuilderService.BuildBaseHeaderColumnsWithoutSort(queryModel);

            if (headerColumns != null)
            {
                headerColumns.Insert(RoleColumnIndex, new HeaderColumns { HeaderText = "Role", Width = 100, Name = "Role" });

                if (queryModel.IsNormalMode)
                {
                    headerColumns.Add(new HeaderColumns { HeaderText = "House PT", Width = 80, Name = "HousePositionTaking", CustomCellType = ExcelCellType.Percentage });
                }
            }

            return headerColumns;
        }

        private List<GridDataRow> BuildBodyRows(List<UserNameViewStatisticsModel> statistics, bool isNormalMode, bool viewByInteger)
        {
            var dataRows = from item in statistics select BuildDataRow(item, isNormalMode, viewByInteger);
            return dataRows.ToList();
        }

        private List<GridDataRow> BuildFooter(UserNameViewStatisticsModel grandTotal, bool isNormalMode, bool viewByInteger)
        {
            var dataRow = BuildFooterDataRow(grandTotal, isNormalMode, viewByInteger);
            return new List<GridDataRow> { dataRow };
        }

        private GridDataRow BuildDataRow(UserNameViewStatisticsModel statistic, bool isNormalMode, bool viewByInteger)
        {
            var dataRow = gridDataRowBuilderService.BuildBaseDataRow(statistic, viewByInteger);
            dataRow.Columns.Insert(UserNameColumnIndex, new Columns { Name = "ReportBy", Value = statistic.ReportBy, CellAlignment = HAlignment.Left });
            dataRow.Columns.Insert(CustIdColumnIndex, new Columns { Name = "CustID", Value = statistic.ReportById, CellAlignment = HAlignment.Center });
            dataRow.Columns.Insert(RoleColumnIndex, new Columns { Name = "Role", Value = statistic.RoleName, CellAlignment = HAlignment.Center });

            if (isNormalMode)
            {
                dataRow.Columns.Add(new Columns { Name = "HousePositionTaking", Value = statistic.HousePositionTaking, CellAlignment = HAlignment.Right });
            }

            return dataRow;
        }

        private GridDataRow BuildFooterDataRow(UserNameViewStatisticsModel statistic, bool isNormalMode, bool viewByInteger)
        {
            var dataRow = gridDataRowBuilderService.BuildBaseDataRow(statistic, viewByInteger);

            if (dataRow != null)
            {
                dataRow.Columns.Insert(UserNameColumnIndex, new Columns { Name = "ReportBy", Value = statistic.ReportBy, CellAlignment = HAlignment.Right });
                dataRow.Columns.Insert(CustIdColumnIndex, new Columns { Name = "CustID", Value = string.Empty, CellAlignment = HAlignment.Center });
                dataRow.Columns.Insert(RoleColumnIndex, new Columns { Name = "Role", Value = string.Empty, CellAlignment = HAlignment.Center });

                if (isNormalMode)
                {
                    dataRow.Columns.Add(new Columns { Name = "HousePositionTaking", Value = string.Empty, CellAlignment = HAlignment.Right });
                }
            }

            return dataRow;
        }
    }